import{x as i,p as e}from"./chunk-WWGJGFF6-yJ28wCyU.js";import{B as s}from"./BlogPage-BfQOaJjD.js";import{C as n}from"./Copyrightslug-DjI77uKa.js";import"./BlogData-VHqoH-6J.js";import"./Breakpoints-B6Sa9p59.js";import"./Container-BgmzfVBG.js";import"./DefaultPropsProvider-D1dgUI_D.js";import"./Typography-D1-72eUy.js";import"./typographyClasses-peJ8MIGc.js";const t={floatImageRight:{display:"block",float:"right",marginTop:16,marginLeft:32,marginBottom:32,width:320,maxWidth:"50%"},table:{fontSize:"1.0rem",marginTop:"24px",marginLeft:24,marginBottom:"24px",borderCollapse:"collapse",borderTop:"1px solid black",borderBottom:"1px solid black"},thead:{borderBottom:"1px solid black"},tableHeader:{textAlign:"left",paddingRight:"24px",paddingLeft:8,paddingBottom:"4px"},tableCell:{paddingRight:"24px",paddingTop:"4px",paddingLeft:8,paddingBottom:"4px"},tableCellBorder:{borderBottom:"1px #C0C0C0 solid"},tableLegend:{marginLeft:64}},f=i(function(){return e.jsxs(s,{route:"/MxrDynaComp",children:[e.jsx("img",{src:"./thumb/DynaCompThumb.jpg",style:t.floatImageRight}),e.jsx("p",{children:"The MXR Dyna Comp is a classic 1970s compressor pedal, highly prized by guitarists and collectors of guitar effects pedals. Unlike many compressors, the Dyna Comp is based on an OTA (Operational Transconductance Amplifier) rather than an op amp or photo-diode, giving it the distinctive sound OTA-based compressors are known for."}),e.jsx("p",{children:"This analysis examines how the circuit works at the component level while also drawing conclusions about the pedal's high-level behavior in order to provide insight into how one might more effectively use the pedal in an actual guitar rig."}),e.jsx("p",{children:"Non-technical readers are encouraged to enjoy the graphs and diagrams, while dwelling lightly over detailed component-level descriptions. The analysis provides insights into high-level pedal behavior inadequately documented in the owner's manual (what does that Sensitivity knob really do?). The final section discusses what makes the Dyna Comp distinctive among guitar compressors and characterizes its sound through analysis rather than subjective descriptions."}),e.jsx("p",{children:"This analysis is based on LTSpice simulations of the MXR Dyna Comp circuitry. A link to the LTSpice model file is provided in the references section."}),e.jsx("h2",{children:"Circuit Overview"}),e.jsx("p",{children:"The circuit can be separated into several functional blocks, each responsible for a specific aspect of the compression effect. Each of these blocks will be analyzed in more detail below."}),e.jsxs("div",{style:{display:"grid",gridTemplateColumns:"auto 1fr",gap:"16px",marginTop:"24px"},children:[e.jsx("div",{children:e.jsx("strong",{children:"Power supply:"})}),e.jsx("div",{children:"Provides conditioned power rails for the rest of the circuit."}),e.jsx("div",{children:e.jsx("strong",{children:"Input buffer:"})}),e.jsx("div",{children:"Buffers and conditions the incoming guitar signal."}),e.jsx("div",{children:e.jsx("strong",{children:"Transconductance amp:"})}),e.jsx("div",{children:"Applies the compressor envelope gain to the incoming signal."}),e.jsx("div",{children:e.jsx("strong",{children:"Envelope generator:"})}),e.jsx("div",{children:"Generates a current signal which controls gain of the transconductance amplifier, in order to compress the input signal."}),e.jsx("div",{children:e.jsx("strong",{children:"Output:"})}),e.jsx("div",{children:"The actual output signal is generated by tapping the output of transistor Q3 in the Envelope Generator section. The output then applies the Volume control pot to the final effect output."})]}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaCompSchematic.svg",target:"_blank",rel:"noopener noreferrer",children:e.jsx("img",{src:"./img/DynaCompSchematic.svg",style:{display:"block",marginTop:32,marginBottom:0,maxWidth:"100%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 1: Schematic of the MXR Dyna Comp circuit."})]}),e.jsx("h2",{children:"Signal Volume Measurements Conventions"}),e.jsx("p",{children:'By industry convention, guitar pickup voltage levels are measured in dBu, which is an RMS voltage measurement in decibels relative to 0.775 volts RMS. This analysis also uses peak-to-peak measurements stated in "dBV(pp)": decibels relative to 1 Volt peak-to-peak.'}),e.jsx("p",{children:"Converting between RMS and peak-to-peak measurements is problematic, as the conversion depends on waveform shape, harmonic content, and phase relationships."}),e.jsx("p",{children:"For reference, the following conversions apply to this document:"}),e.jsxs("table",{style:t.table,children:[e.jsxs("thead",{style:t.thead,children:[e.jsxs("tr",{children:[e.jsx("th",{style:t.tableHeader,children:"Waveform"}),e.jsx("th",{style:t.tableHeader,children:"0dBu"}),e.jsx("th",{style:{...t.tableHeader,paddingRight:0},children:"0dbV(pp)"})]})," "]}),e.jsxs("tbody",{children:[e.jsxs("tr",{style:t.tableCellBorder,children:[e.jsx("td",{style:t.tableCell,children:"Sin"}),e.jsx("td",{style:t.tableCell,children:"= 2.2dbV(pp)"}),e.jsx("td",{style:t.tableCell,children:"= -2.2dBu"})]}),e.jsxs("tr",{children:[e.jsx("td",{style:t.tableCell,children:"Square"}),e.jsx("td",{style:t.tableCell,children:"= 3.0dbV(pp)"}),e.jsx("td",{style:t.tableCell,children:"= -3.0dBu"})]})]})]}),e.jsx("p",{style:t.tableLegend,children:"Table 1: Conversion between dBu and dBV(pp) for common waveforms."}),e.jsx("p",{children:"The MXR Dyna Comp lacks an input volume control, assuming input signals fall within typical guitar pickup ranges. Since compressors are usually placed first in an effect chain, guitarists can adjust input levels using their guitar's volume control."}),e.jsx("p",{children:"However, voltages vary considerably between pickup types—a modern humbucker outputs significantly higher voltages than a vintage Telecaster single-coil. These differences affect envelope release behavior, as will be discussed later."}),e.jsx("p",{children:"The following table shows typical voltage levels by pickup type. These are rough guidelines; actual voltages vary considerably between pickup models."}),e.jsxs("table",{style:t.table,children:[e.jsx("thead",{style:t.thead,children:e.jsxs("tr",{children:[e.jsxs("th",{style:t.tableHeader,children:["Pickup",e.jsx("br",{})," Type"]}),e.jsxs("th",{style:t.tableHeader,children:["Attack",e.jsx("br",{})," (dBu)"]}),e.jsxs("th",{style:t.tableHeader,children:["Attack",e.jsx("br",{})," (dbV(pp))"]}),e.jsxs("th",{style:t.tableHeader,children:["Sustained",e.jsx("br",{})," (dBu)"]}),e.jsxs("th",{style:{...t.tableHeader,paddingRight:0},children:["Sustained",e.jsx("br",{})," (dbV(pp))"]})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{style:t.tableCellBorder,children:[e.jsx("td",{style:t.tableCell,children:"Vintage Single-Coil"}),e.jsxs("td",{style:t.tableCell,children:["-8 to",e.jsx("br",{}),"-4 dBu"]}),e.jsxs("td",{style:t.tableCell,children:["-6 to",e.jsx("br",{}),"-2 dbV(pp)"]}),e.jsxs("td",{style:t.tableCell,children:["-18 to",e.jsx("br",{}),"-14 dBu"]}),e.jsxs("td",{style:t.tableCell,children:["-16 to",e.jsx("br",{}),"-12 dbV(pp)"]})]}),e.jsxs("tr",{style:t.tableCellBorder,children:[e.jsx("td",{style:t.tableCell,children:"Modern Single-Coil"}),e.jsxs("td",{style:t.tableCell,children:["-4 to",e.jsx("br",{}),"0 dBu"]}),e.jsxs("td",{style:t.tableCell,children:["-2 to",e.jsx("br",{}),"+2 dbV(pp)"]}),e.jsxs("td",{style:t.tableCell,children:["-14 to",e.jsx("br",{}),"-10 dBu"]}),e.jsxs("td",{style:t.tableCell,children:["-12 to",e.jsx("br",{}),"-8 dbV(pp)"]})]}),e.jsxs("tr",{style:t.tableCellBorder,children:[e.jsx("td",{style:t.tableCell,children:"Humbucker"}),e.jsxs("td",{style:t.tableCell,children:["0 to",e.jsx("br",{}),"+4 dBu"]}),e.jsxs("td",{style:t.tableCell,children:["+2 to",e.jsx("br",{}),"+6 dbV(pp)"]}),e.jsxs("td",{style:t.tableCell,children:["-10 to",e.jsx("br",{}),"-6 dBu"]}),e.jsxs("td",{style:t.tableCell,children:["-8 to",e.jsx("br",{}),"-4 dbV(pp)"]})]}),e.jsxs("tr",{children:[e.jsx("td",{style:t.tableCell,children:"Active Pickup"}),e.jsxs("td",{style:t.tableCell,children:["+4 to",e.jsx("br",{}),"+8 dBu"]}),e.jsxs("td",{style:t.tableCell,children:["+6 to",e.jsx("br",{}),"+10 dbV(pp)"]}),e.jsxs("td",{style:t.tableCell,children:["-6 to",e.jsx("br",{}),"-2 dBu"]}),e.jsxs("td",{style:t.tableCell,children:["-4 to",e.jsx("br",{}),"0 dbV(pp)"]})]})]})]}),e.jsx("p",{style:t.tableLegend,children:"Table 2: Typical signal input levels, by pickup type."}),e.jsx("h2",{children:"Power Supply"}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaCompSchematicPs.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaCompSchematicPs.svg",style:{marginTop:32,marginBottom:0,width:500,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 2: Schematic of the power supply block."})]}),e.jsx("p",{children:"The power supply block does basic conditioning of input from the 9V battery (which may actually deliver anywhere between 9.6V and 7V depending on battery type, and how long the battery has been in use)."}),e.jsx("p",{children:"Diode D3 provides protection against reverse connection of the battery. R2 and R17 are a voltage divider that generates a 2.54V power rail which is  used to provide a bias voltage to transistors. Capacitors C6 and C11 ensures that power comes up safely and smoothly when a battery is first connected."}),e.jsx("h2",{children:"Input Buffer"}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaCompSchematicBuffer.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaCompSchematicBuffer.svg",style:{marginTop:32,marginBottom:0,width:500,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 3: Schematic of the input buffer block."})]}),e.jsx("p",{children:"The input buffer block provides a standard high-impedance input buffer for the guitar signal, ensuring minimal loading on the guitar pickups."}),e.jsx("p",{children:"C2, R7 and R5 provide a high-pass filter to remove DC offset and low-frequency noise from the input signal. Together, they provide a high-pass (or a low-cut) filter  with a 36Hz cutoff frequency."}),e.jsx("h2",{children:"Transconductance Amplifier"}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaCompSchematicTa.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaCompSchematicTa.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 4: Schematic of the transconductance amplifier block"})]}),e.jsxs("p",{children:["The transconductance amplifier block modifies the gain of the input signal under control of a feedback signal provided by the Envelope Generator block through the ",e.jsx("em",{children:"gmod"})," connection."]}),e.jsxs("p",{children:["The heart of this block is the CA3080 Operational Transconductance Amplifier (OTA). At OTA is similar in concept to an op-amp, but instead of providing a voltage output, it provides a current output proportional to the input voltage, multiplied by the current flowing into its ",e.jsx("em",{children:"abc"})," pin. The gain of the differential input voltage is controlled by the ",e.jsx("em",{children:"gmod"})," current signal on the schematic. The output of the OTA is equal to"]}),e.jsxs("p",{style:{marginLeft:64},children:["Iout = G",e.jsx("sub",{children:"m"})," * (V+ - V-)"]}),e.jsxs("p",{children:["where G",e.jsx("sub",{children:"m"})," is proportional to input current on the ",e.jsx("em",{children:"abc"})," pin."]}),e.jsx("p",{children:"The CA3080 is no longer in production, and is available only as NOS. However, a commonly used substitute is the LM13700, which is not pin-compatible, but is, apparently, otherwise almost an exact replacement for the CA3080. The LM13700 has better linearity over a wider range of input voltages, but an be degraded to match the linearity of the CA3080 by disconnecting the Diode Bias pin (pin 2). The Ross Compressor (another famous and highly-prized OTA-based compressor), and many rebuilds of the MXR Dyna Comp uses the TI LM13700 instead of a CA3080. The Ross compressor is, in fact, a functionally exact replica of the MXR Dyna Comp, with all the circuitry participating in processing of audio being identical (save for the replacement of the CA3080 with an LM13700, with the Diode Bias pin disconnected)."}),e.jsxs("p",{children:["The OTA's transconductance is controlled by the current flowing into its ",e.jsx("em",{children:"abc"})," pin, which is connected to the ",e.jsx("em",{children:"gmod"})," input connection on the schematic, coming from the Envelope Generator block. Somewhat unintuitively, the CA3080 keeps the voltage of the Iabc pin at a constant voltage of slightly under 1.4V, so it's important to remember that it is the current flowing through ",e.jsx("em",{children:"gmod"}),', not the voltage that controls the gain of the OTA. 1.4V happens to be two transistor bias drops, which probably accounts for the acronym: "abc" = "amplifier bias current", which encompasses the idea that the pin provides current control at an a internal amplifier bias voltage.']}),e.jsx("p",{children:"Instead of using a phase splitter, a passive resistor/capacitor network applies a high-pass filter to the V+ input of the CA3080. The difference between the filtered V+ signal, and the unfiltered V- signal then provides the differential input to the OTA. In the process, the 1dBU voltage swing of the guitar input is converted to a nominal range of about +/-50mV for a 1kHz input signal across the differential inputs of the OTA, which puts the differential voltage in a range where the OTA can operate linearly without significant distortion across several decades of magnitude."}),e.jsxs("p",{children:["In the discussion that immediately follows, small-signal frequency response analysis is conducted by temporarily pin to a constant 0.6µA current source, which effectively disables the envelope generator. Because ",e.jsx("em",{children:"gmod"})," varies over time, it is impossible to do a meaningful small-signal static AC analysis of frequency response unless the envelope generator is temporarily disabled. Transient analysis of the spectral response of the circuit, with the envelope generator connected (which confirms the static AC small-signal analysis), will be deferred until later in the analysis."]}),e.jsx("p",{children:"Figures 5 through 7 show small-signal frequency responses for signals going into and out of the OTA. Responses are measured relative to the V(Vin) guitar input, so they include the low-cut filter applied in the input buffer block."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_spec_ota_pos.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_spec_ota_pos.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 5: Small signal response, guitar input to the ota_pos input of the CA3080. Signal going to the ota_neg input is not filtered (although both inputs inherit the low-cut filter from the input block. The filter network before ota_pos applies a high-cut (low-pass) filter at about 10KHz."})]}),e.jsx("p",{children:"More interesting is the frequency response of the difference between the V+ and V- inputs, which is the actual differential voltage input to the OTA (and therefore the frequency response of the OTA output current signal)."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_spec_ota_diff.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_spec_ota_diff.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 6: Small signal response of V(ota_pos) minus V(ota_neg)."})]}),e.jsx("p",{children:"The net result of the passive filter before the CA3080 is to apply a massive 15dB+ high-frequency boost to the signal being fed to the OTA, and an additional low cut in addition to the input buffer low-cut, that brings the effective low-cut cutoff frequency up to about 60Hz."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_spec_ota_out.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_spec_ota_out.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 7: Small signal frequency response of the voltage at the output of the OTA (envelope generator disabled)."})]}),e.jsxs("p",{children:["The C1/R6 network adds a voltage bias to the current output of the OTA for transistor Q2 that follows in the Envelope Generator block, while also applying a high-cut filter with an Fc of about 8.5khz. The effect of this high-cut filter is to substantially remove the high-frequency boost on the voltage signal at ",e.jsx("em",{children:"ota_out"})," (see Figure 7). The current output, ",e.jsx("em",{children:"I(ota_out)"}),", is a linear function of the frequency response of ",e.jsx("em",{children:"V(ota_pos)-V(ota_neg)"}),", and therefore produces the same frequency response curve as shown in Figure 6, including the high-frequency boost."]}),e.jsxs("p",{children:["Taken together, the actual purpose of the filter networks before and after the OTA becomes clear. They provide passive conversion of the OTA's output current signal to a voltage signal (with an additional high cut (low pass) filter applied at a cutoff frequency of about 8.5kHz), which would normally require an active integrator circuit of some sort. The high cut is more likely a side-effect of the fact that the passive integrator filter is an approximation, rather than being a deliberate design choice. The OTA does provide a convenient way to apply the compressor envelope  gain to the input signal via the ",e.jsx("em",{children:"abc"})," pin over a wide range of values, with low noise rations. But, ironically, it produces an inconvenient current output, since the transistor that follows (Q3) in the Envelope Generator section needs a voltage signal at its base. With the C1/R6 filter network applied, the current on the connection between the OTA and the following transistor faithfully replicates the frequency boost of the OTA differential voltage input; but the voltage carries a a signal without the frequency boost—in fact, it applies an 8.5kHz high-cut instead."]}),e.jsxs("p",{children:[" When the envelope generator is connected, during normal circuit operation, the frequency response at ",e.jsx("em",{children:"ota_out"})," is considerably more complicated. The frequency response is no longer linear, because it depends on ",e.jsx("em",{children:"gmod"})," which is varying over time, and, depending on value of the Sensitivity control,  and signal input strength. When the Sensitivity knob is set to less than 0.5, the OTA operates almost entirely within the linear range of the OTA amplifier. But the OTA does occasionally clip during transient picking attacks. Clipping behavior in the OTA will be analyzed in more detail, after we have complete analysis of the compression envelope generator. When the Dyna Comp is processing sustained notes, with the compression envelope fully attacked, the OTA will be operating in more-or-less linear response range, with more-or-less constant gain, and the frequency response curve will be the one show in Figure 7: a slightly dark tone with a low cut at about 60hz, a high cut at about 8.5kHz, and flat response between the two cutoff frequencies."]}),e.jsx("p",{children:"The TRIM pot is used to adjust the balance of the V+ and V- inputs to the OTA. The official position of MXR/Dunlop is that the TRIM pot should always be set to mid-position."}),e.jsx("h2",{children:"Envelope Generator"}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaCompSchematicEg.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaCompSchematicEg.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 8: Envelope generator block"})]}),e.jsxs("p",{children:["The envelope generator block is responsible for generating the the signal that controls the compressor envelope gain. The control signal is sent back to the OTA amplifier section via the ",e.jsx("em",{children:"gmod"})," connection. Note that the sense of the compression envelope is inverted from that of an ADSR envelope generator. As the compressor attacks, it reduces overall gain in order to bring the picking transient in the input signal to constant output level; and as it releases, it increases gain in order to maintain a constant output level of  sustained notes."]}),e.jsx("p",{children:"Transistor Q3 is a phase splitter, which provides both inverted and non-inverted outputs of the signal coming from the transconductance amplifier. Output voltages will not carry the high-frequency boost; but (by inspection) output currents from the transistor do. However, that's more of a curiosity than a useful fact, since circuitry from this point on is more directly concerned with voltage levels than currents."}),e.jsx("p",{children:"The key to understanding how the envelope generator block works is to recognize that the Q4 and Q5 transistors are operating mostly reverse-biased. When the voltage at the base of Q4 or Q5 exceeds the bias point (which occurs very briefly in normal operation), the transistors open and allow charge to  drain from the C5 capacitor to ground via the Q4 and Q5 transistors."}),e.jsxs("p",{children:["The charge on the C5 capacitor constitutes the state of the envelope generator. When the Dyna Comp powers up, C5 will start consuming current from Vs through R3 until the voltage across C5 reaches Vs (~+9V), at which point, the voltage at ",e.jsx("em",{children:"env_c"})," will also be +9V."]}),e.jsxs("p",{children:["Let's examine the circuitry around ",e.jsx("em",{children:"det_p"})," first. Capacitor C4 is a DC blocker. The voltage on the det_p will have a DC offset of zero volts. When ",e.jsx("em",{children:"Vin"})," (the guitar input signal) is zero, then ",e.jsx("em",{children:"det_p"})," will be at zero volts as well. Since this is below the bias voltage of Q5 (about +0.7V), Q5 will be reverse biased, and current cannot flow through transistor Q5. When the ",e.jsx("em",{children:"V(det_P"})," exceeds the bias voltage of Q5, then Q5 will start to conduct, causing the voltage of ",e.jsx("em",{children:"det_p"})," to drop, and charge flows out of the C5 capacitor to ground via the Q5 transistor."]}),e.jsxs("p",{children:["The circuitry around ",e.jsx("em",{children:"det_n"})," works in a similar manner, except it works on an inverted version of the input signal. Q4 and Q5 act as threshold detectors. C5 is allowed to discharge either when the voltage of the input signal exceeds +0.7V (through Q5), or when the voltage of the input signal is less than -0.7V (via Q4). This mechanism provides the attack of the compressor envelope. The rate at which C5 discharges determines how quickly the compressor attacks."]}),e.jsx("p",{children:"When both Q4 and Q5 are non-conducting (when V(det_n) < 0.7V, and V(det_p) < 0.7V), C5 will start to charge again through R3 to Vs, which causes V(env_c) to rise back +9V. The charging rate determines the release time of the compressor. In the absence of input signal, it takes about 1.5 seconds for the C5 capacitor to fully discharge, and thus for the compressor envelope to fully release."}),e.jsx("p",{children:"Diodes D1 and D2 provide protection for their respective Q5 and Q4 transistors, ensuring their base voltages do not fall below one diode drop below ground (about -0.6V in this case). Otherwise, they have no effect on signal output."}),e.jsxs("p",{children:["Transistor Q2 acts as a buffer between ",e.jsx("em",{children:"env_c"})," and the path to the Iabc pin of the OTA. The voltage at the emitter of Q2 is more or less equal to the voltage at ",e.jsx("em",{children:"env_c"}),"; and the buffering provided by Q2 minimizes the current leaking from C5 to the OTA ",e.jsx("em",{children:"abc"})," pin."]}),e.jsxs("p",{children:[" The Sensitivity pot (U1) and R14 convert the voltage at the emitter of Q2 into current flowing into the ",e.jsx("em",{children:"abc"})," pin of the OTA, which in turn, determines the gain of the OTA. A lower resistance at U1 causes more current to flow into the ",e.jsx("em",{children:"abc"})," pin; higher resistance causes less current to flow into the ",e.jsx("em",{children:"abc"})," pin."]}),e.jsxs("p",{children:["Considering the system in total, the feedback loop to the OTA via ",e.jsx("em",{children:"gmod"})," is responsible for compressing the input signal. The system works to ensure that the gain of the OTA is adjusted such that the peak voltages at ",e.jsx("em",{children:"det_p"})," and ",e.jsx("em",{children:"det_n"}),"are hovering around the value where Q5 and/or Q4 start conducting. As the input voltage varies, the envelope detector works to keep the gain of the OTA at the point where the input signal with envelope applied keeps the maximum and minimum voltages being applied to Q4 and Q5  close to their bias points. The signal is boosted to the threshold voltage levels after which the volume of the output will not increase any further."]}),e.jsx("p",{children:"As the envelope generator attacks, voltage drops, which reduces I(abc) current of the OTA, which reduces the gain of the OTA. When releasing, voltage rises at the emitter of Q2, which increases the I(abc) current of the OTA, which increases the gain of the OTA."}),e.jsxs("p",{children:[" Once C5 has fully discharged, and ",e.jsx("em",{children:"det_c"})," has returned to +9V, the gain of the OTA can no longer be increased. So, subsequent decreases in signal level will not increase the compressor gain any further. This determines the threshold of the compressor."]}),e.jsx("p",{children:"However, because it takes a long time for C5 to discharge (about 2 seconds), in practice, when playing, the compressor envelope will almost always be partially engaged while playing."}),e.jsx("p",{children:"Figure 9 shows how this all works together to produce a compression envelope."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/CapacitorCharging.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/CapacitorCharging.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 9: Operation of the envelope generator."})]}),e.jsxs("p",{children:["Figure 9(a) shows the input signal fed into the circuit simulation. In this case, a 1kHz pulse at 0.5dBU. 9(b) shows the voltage at ",e.jsx("em",{children:"det_p"}),". Clipping at the bottom of V(det_p) indicates the point at which diode D1 has begun to conduct and dump voltage to ground. Clipping at the top of ",e.jsx("em",{children:"det_p"})," indicates the point at which Q5 has started to open up and dump current from the C5 capacitor. 9(c) shows the current passing from capacitor C5 to ground via Q5 when when V(dept_p) reaches the 0.7V transistor bias point.  9(d) indicates how the voltage at ",e.jsx("em",{children:"env_c"})," decreases as capacitor C5 discharges. Note that Q4 is doing the same thing, but with an inverted signal of opposite phase, so steps are visible on the V(env_c) curve as Q4 and Q5 take turns dumping charge from C5."]}),e.jsx("p",{children:"The potentiometer U1 (Sensitivity) and R14 convert the voltage at the emitter of Q2 to a current signal, which controls the gain of the OTA. The effect of the Sensitivity pot will be analyzed in detail in  a subsequent section."}),e.jsx("h2",{children:"Output Stage"}),e.jsxs("p",{children:["A compressed signal is taken from the output of transistor Q3 in the envelope generator block, just before it is fed into the negative envelope detector. Current flowing through this path causes a slight reduction in magnitude of the signal at ",e.jsx("em",{children:"V(det_n)"}),", but this effect is negligible. The practical consequence is that it means that usually it is Q5 which is sitting exactly at its bias point, while Q4 is slightly below its bias point when the envelope is fully attacked; but this is a point of curiosity rather than a practical concern."]}),e.jsx("p",{children:"The output signal is then passed through a high-pass filter formed by R12 and C8, which act as a DC blocker. The small signal frequency response of the signal after the DC blocker is the sames as show in figure 7, but with one additional DC blocker applied."}),e.jsx("p",{children:"The audio-tapered Output pot (U2) provides a simple passive volume control circuit which divides the final compressed signal by the effective resistances of the U2 pot."}),e.jsx("h2",{children:"Compression Envelope Behavior"}),e.jsx("p",{children:"The Sensitivity pot (U1) controls how much the envelope generator affects the OTA gain."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_env_attack_stepped.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_env_attack_stepped.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 10: Effect of the Sensitivity pot on envelope attack. Input consists of a pulsed 480Hz sin wave at -12dbV(pp) or -9.8dBu. Panel (a) shows current input to the OTA abc pin. Panel (b) shows the effect OTA gain in dB relative to the envelope sustain point."})]}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_env_release_stepped.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_env_release_stepped.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 11: Effect of the Sensitivity pot on envelope release."})]}),e.jsxs("p",{children:["Figure 10 shows how the gain of the OTA changes as the Sensitivity pot is adjusted during the attack of a 1kHz sin wave pulse with a signal level of -12dBV(pp) (-9.8dBu). The attack of the compressor is visible as the gain of the OTA (controlled by ",e.jsx("em",{children:"I(abc)"}),")drops over time. The gain of the OTA is directly linearly proportional to the current flowing into the OTA's IAbc pin. For each of the settings, the attack time of the envelope is about 12ms, although this varies with the Sensitivity pot setting. For the given input, I(abc) eventually settles at about 6µA, at which point, the envelope has fully attacked. The actual settling point of I(abc) and the OTA gain varies depending on the voltage range (peak to peak) of the input signal; but regardless of the input signal level, the envelope generator will settle at a point where the final output of the effect is a consistent 0.3V, or about -4.4dbV(pp) (-7.6dBu), when the Volume pot is set to 1.0. The implication of this is that the Dyna Comp compressor has a compression ration of zero: it will always seek to a constant output volume when playing sustained notes, as long as the envelope generator is engaged. As a result, variations of expressive dynamics in the input are completely eliminated in the output signal. This occurs regardless of the setting of the Sensitivity pot."]}),e.jsx("p",{children:"The general effect of the compressor attack is that, when presented with a transient increase in volume, the output voltage will increase before the envelope generator has a chance to compensate, and then the output signal level will decay back to 0.3V as the envelope generator catches up.  As a consequence, the OTA can and will be driven into overdrive and temporary clipping, particularly when sensitivity settings are high, and the envelope generator has substantially release back to maximum gain. Clipping behavior of the OTA in response to input volume spikes will be examined later on. The point at which the OTA current output clips, roughly corresponds to an output signal level of +/-2V (about +7dBV(pp) or +4dBu). Technically, this is overvoltage for a standard Hi-Z effect or amplifier input, so downstream effects and amplifiers may further clip the output signal of the Dyna Comp when this occurs."}),e.jsx("p",{children:"Attack times do vary depending on the value of the Sensitivity pot, but for all sensitivity values, the envelope attack has substantially completed about 9ms after onset of the initial input signal. But because the total excursion of the envelope gain has been altered, the attack rates vary."}),e.jsx("p",{children:"Figure 11 shows the behavior of the compression envelope when releasing. In the example shown in Figure 11, the envelope generator has only released about 1/4 of the way back to idle state when the next sin pulse arrives, 500ms later. The practical implication of this is that, when a guitarist plays a musical phrase, the gain excursion of the compressor envelope during picking attacks in the middle of the phrase will be considerably less than the initial gain excursion from fully-idle state. Again, release times are more or less the same regardless of Sensitivity value, but because the total excursion of the envelope has been altered, the release rates vary."}),e.jsx("p",{children:"The threshold of a compressor is the signal level below which the compressor will no longer compress input signals. For the Dyna Comp the compressor threshold occurs when capacitor C5 has fully discharged, and the output of the envelope generator sits at +9V. At this point, OTA gain can no longer be increased, and the compressor is fully released."}),e.jsx("p",{children:"The envelope threshold varies by Sensitivity value. It can be inferred by reading off the maximum gain levels on the left side of if figure 10 (b). The test signal used to generate Figure 10 (b) has a volume level of -12dBV(pp). Conveniently, voltage of the output signal, with the envelope fully attacked is 0.3dBV(pp)—close enough to unity gain for the back-of-the-envelope calculations that follow. Because the maximum gain is +32dB when Sensitivity is set to 1.0, we can infer that the corresponding threshold is -32dB lower than the test input signal, which would be (-12dBV-32db) = -44dBV(pp), or about -41dBu."}),e.jsx("p",{children:"Similar calculations for other Sensitivity values give threshold values by Sensitivity settings, the results of which are given in Table 3."}),e.jsxs("table",{children:[e.jsx("thead",{style:t.thead,children:e.jsxs("tr",{children:[e.jsx("th",{style:t.thead,children:"Sensitivity"}),e.jsx("th",{style:t.thead,children:"Maximum Gain"}),e.jsx("th",{style:t.thead,children:"Envelope Threshold"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{style:t.tableCellBorder,children:[e.jsx("td",{style:t.tableCell,children:"0"}),e.jsx("td",{style:t.tableCell,children:"5dB"}),e.jsx("td",{style:t.tableCell,children:"-17dBV(pp) (-14dBu)"})]}),e.jsxs("tr",{style:t.tableCellBorder,children:[e.jsx("td",{style:t.tableCell,children:"0.25"}),e.jsx("td",{style:t.tableCell,children:"10dB"}),e.jsx("td",{style:t.tableCell,children:"-22dBV(pp) (-19dBu)"})]}),e.jsxs("tr",{style:t.tableCellBorder,children:[e.jsx("td",{style:t.tableCell,children:"0.5"}),e.jsx("td",{style:t.tableCell,children:"20dB"}),e.jsx("td",{style:t.tableCell,children:"-32dBV(pp) (-29dBu)"})]}),e.jsxs("tr",{style:t.tableCellBorder,children:[e.jsx("td",{style:t.tableCell,children:"0.75"}),e.jsx("td",{style:t.tableCell,children:"25dB"}),e.jsx("td",{style:t.tableCell,children:"-37dBV(pp) (-34dBu)"})]}),e.jsxs("tr",{children:[e.jsx("td",{style:t.tableCell,children:"1.0"}),e.jsx("td",{style:t.tableCell,children:"32dB"}),e.jsx("td",{style:t.tableCell,children:"-44dBV(pp) (-41dBu)"})]})]})]}),e.jsx("p",{style:t.tableLegend,children:"Table 3: Approximate envelope thresholds by Sensitivity."}),e.jsx("p",{children:"Table 3 figures are very approximate. Simulations were performed with an ideal C-Taper pot for the Sensitivity knob. In physical devices, the C-Taper pot is more likely a 2-segment approximation of an ideal taper. So while the range of thresholds is accurate, intermediate threshold values should be considered very approximate indeed."}),e.jsx("p",{children:"The envelope threshold when Sensitivity is set to 1.0 is generous, and may actually exceed the noise floor on particularly noisy guitar input signals. The envelope threshold when Sensitivity is 0.0, however, is fairly thin. When comparing voltage input levels by pickup type, given in Table 2, it seems that input voltage levels for some single-coil pickups may be too low to meaningfully trigger the compression envelope at all, when Sensitivity is at a minimum value. Single-coil pickups will typically need higher Sensitivity settings to get compression comparable to a guitar with a humbucker pickup and higher input voltages."}),e.jsx("p",{children:"The overall effect of the compressor attack is that, when presented with a transient volume spike in the input signal, the output signal will spike upward above 0.3V, and then decay back to 0.3V as the envelope generator catches up (Volume set to 1.0). Peculiarly, the volume of the picking transient in the output signal depends less on expressive dynamics in the input signal than it does on the state of the envelope generator. For picking transients of the same volume, the volume of the picking transient in the output signal will be higher when the envelope generator is more fully released. And the envelope generator will be more fully released if the sustained input signal of the previous note prior to the picking transient was quieter (or completely silent). This might play a significant role when playing funk licks, where notes are alternately sustained or dampened which will translate in to picking attacks that are more likely to be squishy during portions of a phrase where notes are being damped, for instance. While the tendency to overdrive picking attacks is not be entirely logically predictable, it may perhaps be intuitively controllable, and therefore musically and creatively useful."}),e.jsx("p",{children:"With the Sensitivity pot set to 1.0, and with the compression envelope fully released, the OTA has a gain of about 32dB relative to the gain when the compression envelope has fully attacked. There will, therefore be a significant jump in output volume at the moment the transient begins. Typically, from envelope-idle state, this causes the OTA to clip almost immediately. As the envelope generator starts to engage, the gain of the OTA drops toward the final sustained level, applying  a decay in the gain, and output volume over a period of about 12ms. This effect will be analyzed further in a subsequent section."}),e.jsx("p",{children:"When the Sensitivity pot is set below 0.5, the OTA seems to rarely, if ever, overdrive. And similarly, when the compression envelope has not fully released, picking transients will be much less likely to  overdrive the OTA during picking transients."}),e.jsx("p",{children:"The following conclusions can be drawn about the effect of the Sensitivity pot. The Sensitivity pot scales the effect that the envelope generator has on the gain of the OTA. Attack and release times remain more-or-less constant regardless of the Sensitivity pot. The Sensitivity pot scales the voltage coming out of the envelope generator, and therefore scales the overall excursion of the OTA gain. Increasing the Sensitivity pot decreases the envelope threshold, while also increasing the envelop attack and release rates. Decreasing the Sensitivity pot increases the envelope threshold, while also decreasing the envelope attack and release rates."}),e.jsx("h2",{children:"The Dyna in Dyna Comp?"}),e.jsx("p",{children:"As mentioned earlier, the Dyna Comp applies a significant high-frequency boost to the signal being fed into the OTA. This section examines the question of whether that boost contributes audible frequency-dependent effects when the OTA clips. Intuitively, the OTA should be more likely to clip when present with high-frequency input signals. And this does, in fact turn out to be the case."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/TransientSweep.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/TransientSweep.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 12: Magnitude response of a swept sin wave input signal, envelope generator enabled."})]}),e.jsx("p",{children:"Figure 12 shows the the  behavior of the circuit from Vin to Vout when a swept sine wave is used as input. Note that this plot is not equivalent in any way to a bode plot, and doesn't really say anything about frequency response. There is significant non-linear and time-dependent behavior at play, so the plotted responses are not linearly additive as they should be in a bode plot. What the plot does reveal, however, is frequency-dependent behavior in the overall circuit. The envelope generator should keep gain constant across the at least the part of the swept signal between 100hz and 8.5kHz, and it does. But the plot of I(abc), unexpectedly starts rising slightly above 1kHz. Input volume is constant; output volume is constant, but the OTA gain is not!"}),e.jsx("p",{children:"Probing of the circuit reveals that I(abc) rises because the OTA starts to clip. (See Figure 13)."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_5kclipping.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_5kclipping.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 13: Circuit response to a 5kHz sustained sin wave (envelope fully attacked)."})]}),e.jsx("p",{children:"This may be just a passing curiosity. In practice, guitars will never produce such tones in isolation, so these oddities are unlikely to show up directly, in actual playing conditions, at least for sustained tones. The range of fundamental frequencies in an actual guitar signal range from 87.44Hz (E1 fret 0) to 987.77Hz (E6 fret 20). Experimenting with signals that have plausible overtone series seems to suggest that the phenomenon does not occur with realistic guitar signals. Even for a signal that has been clipped before it enters the Dyn Comp, the envelope generator seems to lock in, substantially, on the magnitude of the fundamental harmonic, with overtones not making enough of a contribution to drive the OTA into clipping. Nor is the effect observed when running simulations that use actual recorded guitar signals as input."}),e.jsx("p",{children:"A more productive way to investigate the frequency response characteristics is to perform spectral analysis of transient analysis of output of the Dyna Comp circuitry in response to non-swept signals."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_clipping.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_clipping.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 14: Clipping during onset of the compressor envelope. Input signal: 1kHz sin wave pulse at -12dBU, Sensitivity at 0.5."})]}),e.jsx("p",{children:"Figure 14 clearly shows the results of OTA clipping during an onset transient."}),e.jsx("p",{children:`The tonal effect of OTA clipping during picking transients is that the overall tone of picking attacks will be brightened, as clipping adds additional distortion product overtones (none of which are inharmonic). This is not a bad thing at all. In fact it's a highly desirable effect, generally, because it imparts a sort of edge-of-break-up brittleness to picking attacks that is very pleasant. In our limited vocabulary for describing guitar effects, overdriving of the OTA during transient offsets imparts "dynamic brightness" to picking attacks that is often described as either "snappy" or "squishy". With higher Sensitivity setting, the OTA overdrives through a significant portion of the envelope attack (as shown in the example above). With lower Sensitivity settings, there is still a transient spike, but the OTA doesn't overdrive, and the decay curve of the spike is more exponential.`}),e.jsx("p",{children:"The asymmetry of the distortion produced by the OTA is also worth discussing. Notice how, in Figure 15, the positive peaks of the output wave are relatively flat, whereas the negative peaks are fattened and gently rounded. The precise reasons for this are buried deep within the implementation of the CA3080. At the point that clipping occurs, the signal is inverted. Clipping at the bottom of the wave (corresponding to the top of the wave in Figure 15) essentially hits a transistor bias point and flattens out quite sharply with the same sort of shape that a diode clipper would produce. Clipping at the top of the wave occurs because the combined operation of the pair of transistors that apply the gain follow an the curve of a hyperbolic tangent function. When operating in linear range, the curve of the tanh function is so insignificant that the distortion is inaudible. But when they are driven above their linear operating range, the curvature of the tanh response function increases, leading to the soft rounded curve found at the bottom of the signals in Figure 14. pair are driven above their linear operating range, which produces a more gradual rounding-off of the waveform. The net effect of this asymmetry is to produce a distorted signal with prominent odd-order harmonics, and very modest second-order harmonic overtones. If there were a way to get the Dyna Comp to produce that kind of distortion during sustained tones, it would produce a very pretty overdrive effect. Unfortunately, the envelope generator seems to prevent that from happening. Once the envelope generator has fully attacked, the OTA will once again be operating in its linear range again."}),e.jsx("p",{children:'If the mystique of the Dyna Comp exists anywhere, it has to be related to the clipping behavior of the Dyna Comp during picking transients. In Figure 15, the OTA has been driven deeply into clipping during the picking transient (about +25db above the sustained level were the clipping behavior not present) and it is kept there through most of the envelope attack time. Subjectively, fans of the Dyna Comp describe it as a "squishy" compressor, which intended to describe how the OTA clips during picking transients. The amount of time spent during the envelope attack in the clipping domain (attributable to well chosen attack times) in combination  with the very pretty distortion, with attractive odd-order harmonic products attributable to the asymmetric clipping behavior of the CA3080 would go a long way toward explaining the appeal of the "OTA Compressor" sound.'}),e.jsx("p",{children:"As previously mentioned, when the OTA is clipping, the Dyna Comp will output overvoltage spikes in the output signal of up to +/- 2V. These transient signals may cause further clipping in downstream amps and effects, which may add further complexity to the sound of the Dyna Comp."}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_480_sin.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_480_sin.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsxs("p",{style:{textAlign:"center"},children:["Figure 15: Spectrum of a sustained -12dBU 480Hz sin wave, with the compression envelope fully attacked, and ",e.jsx("em",{children:"sensitivity_pos=1.0"}),"."]})]}),e.jsx("p",{children:` Figure 15 shows the spectrum of a sustained 480Hz sin wave after the envelope has fully attacked. This provides insight into the harmonic distortion of the circuit when playing sustained tones. Sidebands below -46dB are considered "excellent" THD; sidebands below -60dB are considered "transparent". Informal descriptions of the tonal character of the Dyna Comp often describe it as being "warm"&dash;a term usually reserved for describing the pleasant harmonic distortion that tube amps impart as they approach breakup, consisting primarily of additional perceptible even-order harmonics. This is in fact, not the case, as the analysis shows. The actual tonal character of the Dyna Comp is closer to "transparent", and doesn't really show any evidence of "warmth". The harmonic distortion that is present is caused by the very slight tanh response curve of the gain transistors in the center of the CA3080, when they are operating in linear-response range, but are so small that they are practically audible.`}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_480_square.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_480_square.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsxs("p",{style:{textAlign:"center"},children:["Figure 16: Spectrum of a sustained -12dBU 480Hz square wave with the compression envelope fully attacked, and ",e.jsx("em",{children:"sensitivity_pos=1.0"}),".Both input and output signal are displayed. Spectra have been slightly offset during post-processing to allow side-by-side comparison. "]})]}),e.jsx("p",{children:"Figure 16 shows the spectral response to a sustained 480Hz square wave. A square wave consists of a chain of odd-order harmonics, which we can use to confirm prior static AC analysis of the Dyna Comp (with envelope generator disconnected). The spectra of the input and output signal have been slightly shifted to allow side-by-side comparison. In the original simulation results, both data series have a fundamental at 480hz, and overtone series that are multiples of 480hz, and thus overlay each other."}),e.jsx("p",{children:"The output signal (in red) shows added even-order harmonics which are not present in the input signal (in black). They mirror 2nd-order harmonic distortion seen in the sin wave analysis, and are virtually inaudible. Higher odd-order harmonics show the expected roll-off at 8.5kHz which static AC analysis predicted. There are very slight discrepancies between the expected input and output harmonic magnitudes, which can perhaps be attributed to interference between odd order harmonics in the original signal, and odd-order harmonics contributed by harmonic distortion of the OTA."}),e.jsx("p",{children:'The results of transient analysis largely confirm earlier small-signal AC analysis. For sustained tones, the frequency response of the Dyna Comp circuit slightly darkens the input signal, with a low cut at about 60Hz (not demonstrated), and a high cut at about 8.5kHz. Overall harmonic distortion of sustained tones, is negligible. The tonal character of sustained notes would better be characterized as "transparent", not "warm".'}),e.jsx("h2",{children:"Putting it All Together"}),e.jsxs("div",{children:[e.jsx("a",{href:"./img/DynaComp_Live.svg",target:"_blank",rel:"noopener noreferrer",style:{display:"flex",justifyContent:"center"},children:e.jsx("img",{src:"./img/DynaComp_Live.svg",style:{marginTop:32,marginBottom:0,width:800,maxWidth:"80%"}})}),e.jsx("p",{style:{textAlign:"center"},children:"Figure 17: Simulation results with actual recorded guitar input."})]}),e.jsx("p",{children:"Figure 17 shows the response of the Dyna Comp circuit when fed an actual recorded guitar signal. Panel (b) shows the envelope control signal sent to the base of the OTA (I(abc)), which has a linear relationship to gain applied by the OTA. Panel (c) shows the actual compressed output signal. (Sensitivity=1.0, Volume=1.0)"}),e.jsx("p",{children:"There are several interesting features to note in Figure 17, most of which were identified in prior analysis."}),e.jsx("p",{children:"The first is that dynamics (i.e. expressive variations in volume when playing the instrument) in the original signal during sustained portions of the input have been completely eliminated. The Dyna Comp circuitry has a compression ratio of zero. As expected sustained portions of the signal are brought up to a constant volume regardless of the amplitude of the corresponding input."}),e.jsx("p",{children:"Also interesting is that the dynamics of transients in the output signal do not actually reflect the dynamics of transients in the input signal, but instead reflect the ratio of the loudness of the transient to the loudness of the preceding sustained signal."}),e.jsx("p",{children:"For players who are running their effects chains or amps with significant overdrive, this doesn't really have significant consequences, because overdrive will kill any dynamics in the input signal anyway. It does mean that the Dyna Comp is unsuitable for use in musical contexts where some preservation of dynamic expression is desired. But this is a more-or-less generic problem with compression anyway."}),e.jsx("p",{children:"The Dyna Comp's compression is a bit of a sledgehammer, compared to more elaborate studio compressors which will allow non-zero compression ratios, in order to preserve expressive dynamics. That being said, a typical compression ratio on a studio compressor applied to a guitar signal would be often be around 11:1, which, while not completely eliminating dynamics, comes close enough to it that the difference doesn't matter. And for many musical applications, having a compression ratio of zero is an advantage. When there are downstream distortion/overdrive effects, or amplifiers, having a completely consistent output volume helps to ensure that edge-of-breakup effects occur consistently."}),e.jsx("p",{children:`It's probably worth noting at this point that modern versions of the MXR Dyna Comp (the MXR/Dunlop Dyna Comp Deluxe, for example) have a "Clean" control, which allows wet/dry mixing of the input and compressed output signal. This is a quite brilliant way to address the expressive dynamics problem. The dry signal carries expressive dynamics; the wet signal carries sustained notes, plus potentially squishy transient attacks. Mixing the two produces a result that is not dissimilar to (and might even be identical to) a compressor with a non-flat compression ratio.`}),e.jsx("p",{children:"Of particular interest  are the three large spikes that occur in the output signal during picking transients (at about 0.5s, 1.3s and 1.5s). Two of these spikes reach signal levels of 2V (outside of the displayed X-axis range), and all three indicate that the OTA has clipped on close examination."}),e.jsx("p",{children:'By the standards of a studio compressor, the MXR Dyna Comp is a peculiar version of a compressor. It has a compression ratio of "infinite"—compressed signals sustain at the same level, regardless of input level. And attack rates, release rates, and envelope threshold are all controlled by one single knob: the Sensitivity knob.'}),e.jsx("p",{children:"And the lack of an input gain control seems puzzling, and remains unsettling, even when you realize why it doesn't have to be there. In actual practice, guitarists can use the volume knob on their guitar to trim input signals to the Dyna Comp, since it will almost always be the first effect in an effect chain. Single-coil pickups typically output lower signal levels than humbuckers, and may be -12dB quieter (or more). As a results, players who use single-coil pickups may need to turn up the Sensitivity pot a bit more than players who use humbuckers. While this also changes attack and release rates, the single-coil players probably have enough headroom to make necessary and appropriate adjustments to the envelope release threshold, as long as they keep to higher Sensitivity settings."}),e.jsx("h2",{children:"Common Circuit Modifications"}),e.jsx("p",{children:"The Ross Compressor, another well-known OTA compressor, in fact provides a quite faithful emulation of the Dyna Comp compressor. It adds a couple of extra capacitors around the power rails, but exactly replicates the filter networks before and after the OTA, and exactly replicates the envelope generator circuitry. The Ross Compressor uses a TM13700 OTA, which is a modern substitute for the now-discontinued CA3080. The TM13700 provides slightly better linear range than the CA3080 does, but it can be degraded to match the linear response of the CA3080 by leaving the diode bias pin disconnected. The Ross compressor leaves the diode bias pin disconnected."}),e.jsx("p",{children:`The current production version of the MXR Dyna comp (the MXR/Dunlop MXR Dyna Comp Deluxe), adds two new controls. One is labelled "Clean", and provides Wet/Dry mix of the effect input and output. This is a very effective solution to the expressive dynamics problem with the original Dyna Comp. The other knob is labelled "Tone". Presumably this allows some sort of high-frequency boost to the output, in an attempt to limit the effect of the overall high-cut in the Original Dyna Comp's frequency response, or perhaps slightly extend the high-frequency cutoff of the original Dyna Comp.`}),e.jsx("p",{children:`Attempts to eliminate the high cut also feature prominently as a theme in hobbyist mods of the Dyna Comp circuit. Such attempts are going to be necessarily limited. The most important function of the passive filter networks around the OTA are to provide a second-order linear approximation of an integrator, which is required to convert the OTA's current output signal into a voltage signal that following transistor circuitry can use. The original high-cut filter was most probably not a a design feature, but more a practical consequence of the fact that the integrator is only an approximation, which is plausibly accurate only over a frequency range of 60Hz to 8.5kHz. Any attempts to make major modifications to those filters will provide circuitry that is no longer recognizable as an relative of a Dyna Comp. So attempts to modify the overall tone of the circuitry will have to occur very late in the signal chain, after the OTA stage, and probably after the envelope detector stage as well. It might be possible to extend the flat response of the circuit slightly. Or even to provide a high frequency boost in the 1kHz to 8.5kHz range. But it seems implausible that the 8.5kHz high-cut can be substantially eliminated without dramatically altering the overall character of the effect. That being said, another interesting consequence of providing a Wet/Dry or Clean control is that doing so will restore some of the high-frequency content that is lost in the compressor circuitry. So providing a "Clean" or "Wet/Dry" control may be a more effective way to address the high-cut problem. Because overtones die off fairly quickly in a plucked guitar string, a wet/dry mix will restore high-frequency content in the early part of a plucked note where it counts, even if it does not restore high-frequency content later on when the compressed sustained node dominates, and the higher harmonics aren't present anyway.`}),e.jsx("p",{children:'One final prominent theme in hobbyist mods are modifications to the value of R3, which determines the release time of the compressor envelope. By studio-compressor standards, the release time of the compressor envelope is exceptionally long, which perhaps contributes to the impression that the Dyna Comp has "smooth" compression. Reducing the value of R3 will made the envelope release faster, which will mean that the compressor will be much more active during musical phrases. The most direct effect this will be to increase the amplitude of picking attacks in the output signal in musical phrases. The compressor will still settle on the same sustained gain (and output volume) regardless of release time, but may be able to release further in the intervals between notes in a musical phrase. And when it releases further, it means that the transient spike for the note that follows will be louder. Faster envelope releases would also increases the mystical "squishiness" of the circuit response.'}),e.jsx("h2",{children:"Dialing in the Dyna Comp"}),e.jsx("p",{children:"With knowledge derived from the analysis in hand, we can now recommend a procedure for dialing in settings on the Dyna Comp."}),e.jsx("p",{children:"The Volume knob should initially be set at mid-point. The Dyna Comp compresses signals to a consistent level regardless of the input signal, or the setting of the Sensitivity knob. At mid-point, signals from the output will sustain at about -12dBV(pp) (-9.8dBu), peak at about 0dBV(pp) (+2.2dBU). This is a reasonable level to feed into most downstream effects and amplifiers. You can adjust the volume settings later, once you have the compressor generally dialed in. Increasing the volume may cause downstream non-linear effects and amps to respond more vigorously to clipped picking attacks."}),e.jsx("p",{children:"As a starting point, set the Sensitivity pot to maximum value (1.0). Adjust the volume on your guitar, starting at minimum volume, and bring it up until you start to hear the envelope generator engage (the point at which sustain starts to increases). From there, you can further increase the volume on your guitar until you achieve the sort of sustain you would like."}),e.jsx("p",{children:'The sensitivity pot controls (1) the threshold of the envelope generator: the input volume below which the input signal will no longer compress. One wants the noise floor of your input signal to be below the envelope threshold. Reducing the Sensitivity pot will raise the envelope threshold, and will reduce the loudness of output noise when you are not playing. Reducing the Sensitivity pot also reduces the amount of "squishiness" in the compression. And increasing sensitivity increases the amount of "squishiness" in the compression, if that is something you want. If you are struggling with balancing the two, consider adding a noise gate ahead of the compressor, so that you can maximize "squishiness" without getting appreciable noise while you are not playing. Squishiness mostly disappears with mid-range Sensitivity settings. So if "squishiness" is not something you want, consider lowering the Sensitivity.'}),e.jsx("p",{children:"Single-coil pickups typically have much lower input volumes than humbuckers do. Guitars with single coil pickups will typically need nigher Sensitivity settings to get effects comparable to guitars with humbuckers, and the very lowest Sensitivity settings increase the envelope threshold to the point that the compressor doesn't engage at all."}),e.jsx("h2",{children:"Conclusions"}),e.jsx("p",{children:"Despite its simplicity, the MXR Dyna Comp is a highly effective guitar compressor. It has been used on countless classic recordings, and remains a popular choice among guitarists. The Ross Compressor is a similar effect that has a similar following. Although the Ross compressor has only been mentioned in passing, it should not be a huge surprise that the Ross compressor is in fact functionally identical to the MXR Dyna Comp."}),e.jsx("p",{children:' It is notoriously difficult to describe the tonal character of guitar effects pedals. Describing guitar effects using words is like dancing about architecture. The Dyna Comp is variously described as having a "smooth" compression, a somewhat "dark" tonal character, with an overall "warm" feel. Circuit analysis confirms some of those descriptions, and refutes others.'}),e.jsx("p",{children:`Whether the compression effect is smooth or not is largely a matter of opinion. The Sensitivity control provides limited control over the attack rates, release rates and threshold of the compression envelope. But it does manage to provide reasonable and musical control over a compression effect that will be used strictly for compressing electric guitar signals. The fact that the compression ratio is infinite does make the effect somewhat unusual, and doubtless contributes to its distinctive character. And the very long release times of the compression envelope are particularly well suited for compressing electric guitar input signals.  If the Dyna Comp has "smooth" compression, it is because the attack and release rates are reasonably well matched to typical guitar playing styles, and because the compression envelope has an extremely long release time. While it might be nice to have more direct and explicit control over threshold and attack/release rates, the simple fact is that the Dyna Comp delivers pretty darned good results with just a single knob. And the attack and release rates you can't get are more typically used in studio compressors for vocals and drum tracks than they are for compression of electric guitar signals. Classical guitarists will need to look elsewhere. But classical guitarists pretty much knew that already. Acoustic guitarists may find useful sounds within the range of effects that the Dyna Comp can deliver; but I suspect they, too, will find that more flexible compressors are more useful, or that effects boxes targeted for use with acoustic guitars provide out-of-the-box settings that are more relevant. I don't think that will be a surprise to acoustic guitarists either.`}),e.jsx("p",{children:`Another commonly used descriptor is that the Dyna Comp's compression is slightly "squishy". This is a term that Country players, particularly, seem to think is a desirable quality (although opinion is actually sharply divided). "Squishiness" seems to be valued among funk players as well. The term is  presumably intended to describe the Dyna Comp's tendency to overdrive, sometimes quite heavily following the initial transient of picking attacks. When the Sensitivity pot is set to a high value, the Dyna Comp will produce significant overdrive during picking attacks, for a period of up to 12ms following while the envelope generator struggles to reduce gain to a level where the signal will be a clean sustained note again. "Squishiness" seems like a reasonable term to subjectively describe this phenomenon. This in combination with a tendency to produce attractive odd-order harmonics during clipping seems likely to be a particular component of the Dyna Comp sound.`}),e.jsx("p",{children:`The harmonic  character is not "warm" at all, but is almost (but not quite) "transparent". THD during sustained notes is practically non-existent. "Warm" is a misleading description of the Dyna Comp's tonal character. It would suggest that the circuit produces gentle tube-like breakup, when in fact, it does not.`}),e.jsx("p",{children:'The overall frequency response of the Dyna Comp applies a 10khz high cut, but is otherwise flat. This is indeed the opposite of "bright". It might be wiser to describe the frequency response as "mellow" rather than "dark" in order to avoid confusions with the use of the term "dark" which has a slightly more complicated and nuanced meaning when applied to the overall response of guitar amplifiers and overdrive/distortion pedals. And it avoids the tendency to mythicize what is more of a bug in the Dyna Comp than it is a feature. Unromantically speaking, the Dyna Comp has an 8.5kHz high cut frequency response when sustaining, which it would be better off without. However, nobody could seriously be faulted for describing the Dyna Comp as "dark" given the lack of more precise terms in our vocabulary for describing guitar effects.'}),e.jsx("p",{children:'In short, the Dyna Comp delivers pretty much what it promises: a capable and functional compressor effect, specifically designed for use as a guitar compressor,  with a musically meaningful (if not highly flexible) control of the compressor through a single Sensitivity knob. The distinctive sound of the Dyna Comp can mostly be attributed to  its atypical infinite compression ratio, and its tendency to occasionally sharply overdrive picking transients, leading to a slightly "squishy" compression. The "magic smoke" must surely be attributable to the way the Dyna Comp clips during picking transients, which is a function of the way the CA3080 OTA clips when driven hard: diode clipping on one half of the waveform with soft and rich tanh-style clipping on the other half. It lacks flexible control of compression parameters. The bug is that it does not provide a gentler compression ratio that would reduce but not completely eliminate expressive dynamics.  But feature is that it does provide very consistent sustained response and breakup if there are non-linear amps or distortion/overdrive effects downstream—effects that are going to kill dynamic range anyway.'}),e.jsx("p",{children:"And it does so in a way that is not quite like other compressors that aren't clones to begin with. Its simplicity is part of its charm. It doesn't try to be everything to everyone. Overall, it doesn't matter whether these behaviors are decencies or features. What matters is whether the effect delivers opportunities for creative expression. The MXR Dyna Comp unquestionably does."}),e.jsx("p",{children:"The author hopes that this analysis has shed some light on what the MXR Dyna Comp does and does not do, why it behaves the way it does, and more specifically provide insight into how to best dial in the settings that deliver the creative effects that the MXR Dyna Comp does provide."}),e.jsx("h2",{children:"References"}),e.jsxs("ol",{children:[e.jsxs("li",{children:['R. E. R. Davies. "MXR Dyna Comp LtSpice Model".  ',e.jsx("a",{href:"./downloads/DynaCompLtSpiceFiles.zip",children:"./downloads/DynaCompLtSpiceFiles.zip"})]}),e.jsx("li",{children:'MXR/Dunlop. "MXR Dyna Comp Factory Schematic."'}),e.jsxs("li",{children:['Texas Instruments. "CA3080, CA3080A Operational Transconductance Amplifiers." Datasheet. ',e.jsx("a",{href:"https://www.ti.com/lit/ds/symlink/ca3080.pdf",children:"https://www.ti.com/lit/ds/symlink/ca3080.pdf"})," (accessed December 12, 2025)"]}),e.jsx("li",{children:'O. Kröning, K. Dempwolf, and U. Zölzer. "Analysis and Simulation of an Analog Guitar Compressor." Proceedings of the 14th International Conference on Digital Audio Effects (DAFx-11), Paris, France, September 19-23, 2011.'}),e.jsxs("li",{children:['ElectroSmash. "MXR Dyna Comp Analysis."  ',e.jsx("a",{href:"https://www.electrosmash.com/mxr-dyna-comp-analysis",children:"https://www.electrosmash.com/mxr-dyna-comp-analysis"})," (accessed December 12, 2025)"]}),e.jsxs("li",{children:['Fuzz Central. "Ross Compressor, Squeeze and Stretch." (Archived version) ',e.jsx("a",{href:"https://web.archive.org/web/20250328063014/https://fuzzcentral.ssguitar.com/ross.php",children:"https://web.archive.org/web/20250328063014/https://fuzzcentral.ssguitar.com/ross.php"})]})]}),e.jsx("p",{style:{marginTop:32},children:e.jsx("a",{href:"https://github.com/rerdavies/rerdavies.github.io/discussions/4",children:"🗨 COMMENTS"})}),e.jsx(n,{})]})});export{f as default};
